@app.get(
    "/__COLLECTION__/page"
)
def paginate(
    page:int=1,
    size:int=5__AUTH_PARAMS__
):

    if page < 1 or size < 1 or size > 100:
        raise HTTPException(status_code=422, detail='page must be positive and size must be 1..100')
    start=(page-1)*size
    return __VISIBLE_RECORDS__[start:start+size]
